// One ip-api.com batch request body for up to 100 IPs.
const fields = 'status,message,query,country,countryCode,regionName,city,lat,lon,isp,org,as,hosting';
const batch = $input.all().map((it) => ({ query: it.json.ip, fields })).filter((b) => b.query);
return batch.length ? [{ json: { batch } }] : [];

// ip-api batch answers come back one item per IP. status "fail" means a
// private/reserved address or no data, cached as not_found.
const rows = $input.all()
  .filter((it) => it.json.query)
  .map((it) => ({
    ip: it.json.query,
    provider: 'ipapi',
    status: it.json.status === 'success' ? 'ok' : 'not_found',
    data: it.json,
    ttl_days: 30,
  }));
return rows.length ? [{ json: { rows } }] : [];

const SOURCE_NODE = "PG: IPs needing InternetDB";
const PROVIDER = "internetdb";
const TTL_DAYS = 7;
// Turn per-IP lookups (HTTP node with full response + never error) into
// enrichment rows. 200 = ok, 404 = provider has nothing on the IP (cached as
// not_found so it is not asked again until expiry); anything else (429 rate
// limit, 5xx) is dropped so the IP is retried on a later run.
// SOURCE_NODE, PROVIDER, TTL_DAYS and an optional TRANSFORM(body) are prepended by build.py.
const ips = $(SOURCE_NODE).all().map((it) => it.json.ip);
const rows = [];

// AbuseIPDB wraps its answer in {data: {...}}; the others return the object directly.
function unwrap(body) {
  if (typeof body !== 'object' || body === null) return {};
  return body.data && typeof body.data === 'object' && !Array.isArray(body.data) ? body.data : body;
}

$input.all().forEach((it, i) => {
  const status = it.json.statusCode;
  if (status !== 200 && status !== 404) return;
  rows.push({
    ip: ips[i],
    provider: PROVIDER,
    status: status === 200 ? 'ok' : 'not_found',
    data: typeof TRANSFORM === 'function' ? TRANSFORM(unwrap(it.json.body)) : unwrap(it.json.body),
    ttl_days: TTL_DAYS,
  });
});

return rows.length ? [{ json: { rows } }] : [];

